-- ============================================================================
-- 발표 시연용 리뷰 더미 데이터 (직접 작성, 중복 없음)
--   대상: 삭제되지 않은 맛집 656곳 / 리뷰 2628개 (일반 1972 + 약간 부정 656, 맛집마다 1개)
--   작성자: member 테이블 회원 중 무작위, 같은 맛집에 같은 작성자 없음
--   별점: 5점 687, 4점 691, 3점 619, 2점 557, 1점 74
--   작성일: 2026-08-18 ~ 2026-11-16 사이 무작위
--
-- [실행 순서] 1) 이전 더미 리뷰(마이크로초 777) 삭제  2) 새 리뷰 INSERT  3) AI 요약 비우기
--   한 줄 = 한 문장이라 실행 도구가 줄 단위로 나눠 보내도 문제없습니다.
-- [되돌리기] DELETE FROM review WHERE MICROSECOND(created_at) = 777;
-- ============================================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- 이전 더미 리뷰에 달린 답글 → 이전 더미 리뷰 삭제
DELETE FROM reply WHERE review_id IN (SELECT id FROM (SELECT id FROM review WHERE MICROSECOND(created_at) = 777) t);
DELETE FROM review WHERE MICROSECOND(created_at) = 777;


UPDATE restaurant SET ai_summary = NULL, ai_summary_at = NULL WHERE deleted_at IS NULL;

COMMIT;

-- 확인용: SELECT COUNT(*) FROM review WHERE MICROSECOND(created_at) = 777;   -- 2628 이어야 함
